const fmtINR = (v: number, localization?: LocalizationConfig) =>
  v >= 10_000_000
    ? `${getCurrencySymbolPrefix(localization)}${(v / 10_000_000).toFixed(2)} Cr`
    : v >= 100_000
    ? `${getCurrencySymbolPrefix(localization)}${(v / 100_000).toFixed(2)} L`
    : `${formatAmountWithCurrency(v, localization)}`;

const fmtDate = (d: string) =>
  new Date(d).toLocaleDateString("en-IN", {
    day: "2-digit",
    month: "short",
    year: "numeric",
  } as Intl.DateTimeFormatOptions);

